621	/// Verify the bot repo's `bookmark` is published at origin.
622	///
623	/// Error-raising wrapper over [`bookmark_publish_state`], used by
624	/// `validate-bot` and push preflight. Fixes nothing (decided
625	/// 2026-07-15: no automatic fixing) — the error names the
626	/// `vc-x1 squash-push` resolution and the caller stops.
627	pub fn verify_bot_published(
628	    bot_repo: &Path,
629	    bookmark: &str,
630	) -> Result<(), Box<dyn std::error::Error>> {
631	    let repo_str = bot_repo.to_string_lossy();
632	    match bookmark_publish_state(bot_repo, bookmark)? {
633	        PublishState::InSync => Ok(()),
634	        PublishState::NeverPushed => Err(format!(
635	            "bot repo '{repo_str}': bookmark '{bookmark}' has never been pushed to origin — \
636	             publish it with `vc-x1 squash-push -R {repo_str}`"
637	        )
638	        .into()),
639	        PublishState::Mismatch { local, remote } => Err(format!(
640	            "bot repo '{repo_str}': '{bookmark}' ({}) does not match '{bookmark}@origin' ({}) — \
641	             an earlier publish was likely lost; publish it with \
642	             `vc-x1 squash-push -R {repo_str}`, then retry",
643	            &local[..local.len().min(12)],
644	            &remote[..remote.len().min(12)]
645	        )
646	        .into()),
647	    }
648	}
