650	/// True when `dir` is a workspace's bot repo.
651	///
652	/// Side detection is by *location*, not config content — the
653	/// `[workspace]` block is identical on both sides. `dir` is the bot
654	/// side iff the parent directory's `.vc-config.toml` names `dir` as
655	/// the workspace's `bot`. Paths are canonicalized so relative forms
656	/// (`.claude`) and symlinked tempdirs compare correctly; anything
657	/// unreadable is "not the bot side".
658	pub fn is_bot_dir(dir: &Path) -> bool {
659	    let Ok(dir) = dir.canonicalize() else {
660	        return false;
661	    };
662	    let Some(parent) = dir.parent() else {
663	        return false;
664	    };
665	    let Ok(cfg) = toml_simple::toml_load(&parent.join(VC_CONFIG_FILE)) else {
666	        return false;
667	    };
668	    match toml_simple::toml_get(&cfg, "workspace.bot") {
669	        Some(bot) if !bot.is_empty() => parent.join(bot.trim_start_matches('/')) == dir,
670	        _ => false,
671	    }
672	}
