674	/// Walk up from `start` to find the workspace root.
675	///
676	/// The workspace root is the nearest ancestor whose
677	/// `.vc-config.toml` has a `[workspace] work` key — except when
678	/// that directory is itself the bot repo (the block is identical on
679	/// both sides), in which case the root is its parent. Returns
680	/// `None` if no such config is found up to the filesystem root —
681	/// the caller is in a "plain old repo" (POR) with no vc-x1
682	/// workspace metadata.
683	///
684	/// A pre-0.75.0 legacy root (`path = "/"`, no `work`) is still
685	/// *found* — so the resolvers can reject it with a fix-it message
686	/// via `reject_legacy_config` instead of silently degrading the
687	/// workspace to POR.
688	pub fn find_workspace_root_from(start: &Path) -> Option<PathBuf> {
689	    let mut cur = start.to_path_buf();
690	    loop {
691	        let cfg = cur.join(VC_CONFIG_FILE);
692	        if let Ok(map) = toml_simple::toml_load(&cfg) {
693	            if toml_simple::toml_get(&map, "workspace.work").is_some() {
694	                return if is_bot_dir(&cur) {
695	                    cur.parent().map(Path::to_path_buf)
696	                } else {
697	                    Some(cur)
698	                };
699	            }
700	            // Legacy root marker: the old schema's work side.
701	            if toml_simple::toml_get(&map, "workspace.path").map(String::as_str) == Some("/") {
702	                return Some(cur);
703	            }
704	        }
705	        cur = cur.parent()?.to_path_buf();
706	    }
707	}
