709	/// Error fast on a pre-0.75.0 legacy `[workspace]` schema.
710	///
711	/// A config with `path`/`other-repo` but no `work` predates the
712	/// symmetric work/bot schema. The topology readers treat unknown
713	/// keys as absent, which would silently degrade a dual workspace
714	/// to single-repo — so every resolver calls this first and fails
715	/// with the rewrite instead. A config with both old and new keys
716	/// passes (the new keys drive behavior; `config --validate` flags
717	/// the strays).
718	pub fn reject_legacy_config(dir: &Path) -> Result<(), Box<dyn std::error::Error>> {
719	    let Ok(cfg) = toml_simple::toml_load(&dir.join(VC_CONFIG_FILE)) else {
720	        return Ok(());
721	    };
722	    if toml_simple::toml_get(&cfg, "workspace.work").is_none()
723	        && (toml_simple::toml_get(&cfg, "workspace.path").is_some()
724	            || toml_simple::toml_get(&cfg, "workspace.other-repo").is_some())
725	    {
726	        return Err(format!(
727	            "{}/.vc-config.toml: legacy [workspace] schema (path/other-repo). \
728	             Replace the [workspace] block with the symmetric pair:\n\n\
729	             [workspace]\n\
730	             work = \"/\"\n\
731	             bot = \"/.claude\"\n\n\
732	             (identical in both repos; drop `bot` for a single-repo workspace)",
733	            dir.display()
734	        )
735	        .into());
736	    }
737	    check_workspace_grammar(dir, &cfg)
738	}
