740	/// Enforce the `[workspace]` path grammar (pinned 2026-07-23).
741	///
742	/// Values are ochid path syntax — a leading `/` is the workspace
743	/// root, never filesystem-absolute:
744	///
745	/// - `work` must be exactly `"/"` (the root *is* the work repo;
746	///   any other value would be silently ignored by every reader).
747	/// - `bot` must be `/` + one path component, no trailing slash
748	///   (side detection and the root walk assume the bot repo sits
749	///   directly under the root; the value doubles as the bot-side
750	///   ochid prefix, so an unanchored value corrupts trailers).
751	///
752	/// Called from [`reject_legacy_config`] so every resolver enforces
753	/// the grammar at the same chokepoints; errors loudly, changing
754	/// nothing.
755	fn check_workspace_grammar(
756	    dir: &Path,
757	    cfg: &HashMap<String, String>,
758	) -> Result<(), Box<dyn std::error::Error>> {
759	    if let Some(work) = toml_simple::toml_get(cfg, "workspace.work")
760	        && work != "/"
761	    {
762	        return Err(format!(
763	            "{}/.vc-config.toml: workspace.work is '{work}' but must be exactly \"/\" \
764	             — the workspace root is the work repo by definition; nothing was changed",
765	            dir.display()
766	        )
767	        .into());
768	    }
769	    if let Some(bot) = toml_simple::toml_get(cfg, "workspace.bot")
770	        && !bot.is_empty()
771	    {
772	        let anchored = bot.strip_prefix('/');
773	        let valid = matches!(anchored, Some(rest) if !rest.is_empty() && !rest.contains('/'));
774	        if !valid {
775	            return Err(format!(
776	                "{}/.vc-config.toml: workspace.bot is '{bot}' but must be \"/\" plus one \
777	                 path component, no trailing slash (e.g. \"/.claude\") — the bot repo \
778	                 sits directly under the workspace root and the value doubles as the \
779	                 bot-side ochid prefix; nothing was changed",
780	                dir.display()
781	            )
782	            .into());
783	        }
784	    }
785	    Ok(())
786	}
