788	/// Cwd-anchored wrapper over [`find_workspace_root_from`].
789	pub fn find_workspace_root() -> Option<PathBuf> {
790	    let cur = std::env::current_dir().ok()?;
791	    find_workspace_root_from(&cur)
792	}
