794	/// Resolve the workspace's default `--scope`.
795	///
796	/// Reads `<workspace_root>/.vc-config.toml > [workspace] bot`:
797	///
798	/// - dual workspace (non-empty `bot`) → `Scope([Work, Bot])`
799	/// - single-repo workspace (missing / empty `bot`) →
800	///   `Scope([Work])`
801	/// - POR (no `workspace_root`) → `Scope([Work])` — `scope_to_repos`
802	///   resolves `Side::Work` to cwd's `.` when no root is given, so a
803	///   POR run still operates on the current directory.
804	pub fn default_scope(workspace_root: Option<&Path>) -> Scope {
805	    let Some(root) = workspace_root else {
806	        return Scope(vec![Side::Work]);
807	    };
808	    let cfg = match toml_simple::toml_load(&root.join(VC_CONFIG_FILE)) {
809	        Ok(c) => c,
810	        Err(_) => return Scope(vec![Side::Work]),
811	    };
812	    match toml_simple::toml_get(&cfg, "workspace.bot") {
813	        Some(v) if !v.is_empty() => Scope(vec![Side::Work, Side::Bot]),
814	        _ => Scope(vec![Side::Work]),
815	    }
816	}
817	
818	/// Resolve a `Scope` to concrete repo paths.
819	///
820	/// - `Side::Work` → `workspace_root` (or cwd's `.` when
821	///   `workspace_root` is None).
822	/// - `Side::Bot` → `workspace_root.join(<bot value, root-relative>)`.
823	///
824	/// Errors when `Side::Bot` is requested but the workspace doesn't
825	/// define one (POR or single-repo workspace).
826	pub fn scope_to_repos(
827	    scope: &Scope,
828	    workspace_root: Option<&Path>,
829	) -> Result<Vec<PathBuf>, Box<dyn std::error::Error>> {
830	    if let Some(root) = workspace_root {
831	        reject_legacy_config(root)?;
832	    }
833	    let mut repos = Vec::new();
834	    for side in &scope.0 {
835	        match side {
836	            Side::Work => repos.push(
837	                workspace_root
838	                    .map(Path::to_path_buf)
839	                    .unwrap_or_else(|| PathBuf::from(".")),
840	            ),
841	            Side::Bot => {
842	                let root = workspace_root.ok_or(
843	                    "--scope=bot: not in a vc-x1 workspace (no .vc-config.toml with work = \"/\") — drop --scope or use --scope=work",
844	                )?;
845	                let cfg = toml_simple::toml_load(&root.join(VC_CONFIG_FILE))?;
846	                let bot = toml_simple::toml_get(&cfg, "workspace.bot")
847	                    .filter(|v| !v.is_empty())
848	                    .ok_or(
849	                        "--scope=bot: no bot repo configured. Add `bot = \"/…\"` to .vc-config.toml to enable dual-repo operations",
850	                    )?;
851	                repos.push(root.join(bot.trim_start_matches('/')));
852	            }
853	        }
854	    }
855	    Ok(repos)
856	}
