858	/// Resolve the workspace's bot-repo path, or `None` when it has no
859	/// bot side.
860	///
861	/// The scope-aware prelude for commands that *optionally* work
862	/// against the bot repo (validate-desc / fix-desc): topology comes
863	/// from `default_scope` (the workspace config), not a flag —
864	/// `Ok(None)` means a POR / single-repo workspace, the caller's
865	/// no-op case, while a configured-but-broken bot side still errors
866	/// via `scope_to_repos`.
867	pub fn bot_repo_path(workspace_root: &Path) -> Result<Option<PathBuf>, Box<dyn std::error::Error>> {
868	    match configured_bot_dir(workspace_root)? {
869	        Some(bot) => {
870	            verify_workspace_coherence(workspace_root, &bot)?;
871	            Ok(Some(bot))
872	        }
873	        None => Ok(None),
874	    }
875	}
876	
877	/// The bot dir the workspace config *declares* — a pure config
878	/// read, no on-disk verification.
879	///
880	/// The pre-coherence half of [`bot_repo_path`], for callers that
881	/// resolve the dir before it exists (clone names the local clone
882	/// destination from the just-cloned work repo's config). `Ok(None)`
883	/// when the workspace declares no bot side.
884	pub fn configured_bot_dir(
885	    workspace_root: &Path,
886	) -> Result<Option<PathBuf>, Box<dyn std::error::Error>> {
887	    reject_legacy_config(workspace_root)?;
888	    if !default_scope(Some(workspace_root)).has_bot() {
889	        return Ok(None);
890	    }
891	    let repos = scope_to_repos(&Scope(vec![Side::Bot]), Some(workspace_root))?;
892	    match repos.as_slice() {
893	        [bot] => Ok(Some(bot.clone())),
894	        other => Err(format!(
895	            "configured_bot_dir: expected one repo from scope_to_repos, got {}",
896	            other.len()
897	        )
898	        .into()),
899	    }
900	}
901	
902	/// Resolve the bot repo of a workspace that *requires* one.
903	///
904	/// The dual-only sibling of [`bot_repo_path`] for operations that
905	/// make no sense without a bot side (push): `None` becomes a loud
906	/// error instead of a no-op signal.
907	pub fn require_bot_dir(workspace_root: &Path) -> Result<PathBuf, Box<dyn std::error::Error>> {
908	    bot_repo_path(workspace_root)?.ok_or_else(|| {
909	        format!(
910	            "{}/.vc-config.toml declares no bot repo (`[workspace] bot`) — \
911	             this operation requires a dual workspace",
912	            workspace_root.display()
913	        )
914	        .into()
915	    })
916	}
917	
918	/// Dual-mode entry preflight: verify the two repos' recorded
919	/// topology agrees before any operation acts on it.
920	///
921	/// Checks, in order, erroring with everything known and changing
922	/// nothing (the dual-preflight principle, 2026-07-23):
923	///
924	/// - the bot dir exists (and is a directory);
925	/// - its `.vc-config.toml` loads;
926	/// - the two sides' `[workspace]` blocks are identical (every
927	///   `workspace.*` key compared; the schema promises the block is
928	///   the same file content on both sides).
929	///
930	/// Mid-flight surprises stay per-operation concerns; this gates
931	/// *entry* at the one topology resolver.
932	fn verify_workspace_coherence(root: &Path, bot: &Path) -> Result<(), Box<dyn std::error::Error>> {
933	    if !bot.is_dir() {
934	        return Err(format!(
935	            "workspace incoherent: {}/.vc-config.toml declares bot repo '{}', \
936	             but that directory does not exist — fix the `bot` value or \
937	             restore the directory; nothing was changed",
938	            root.display(),
939	            bot.display()
940	        )
941	        .into());
942	    }
943	    let root_cfg = toml_simple::toml_load(&root.join(VC_CONFIG_FILE))?;
944	    let bot_cfg = toml_simple::toml_load(&bot.join(VC_CONFIG_FILE)).map_err(|e| {
945	        format!(
946	            "workspace incoherent: bot repo '{}' has no readable {VC_CONFIG_FILE} \
947	             ({e}) — the [workspace] block must be identical on both sides; \
948	             nothing was changed",
949	            bot.display()
950	        )
951	    })?;
952	    let ws_keys = |m: &HashMap<String, String>| -> Vec<(String, String)> {
953	        let mut v: Vec<_> = m
954	            .iter()
955	            .filter(|(k, _)| k.starts_with("workspace."))
956	            .map(|(k, val)| (k.clone(), val.clone()))
957	            .collect();
958	        v.sort();
959	        v
960	    };
961	    let (root_ws, bot_ws) = (ws_keys(&root_cfg), ws_keys(&bot_cfg));
962	    if root_ws != bot_ws {
963	        return Err(format!(
964	            "workspace incoherent: the [workspace] blocks differ — they must be \
965	             identical on both sides; nothing was changed\n\
966	             {}/{VC_CONFIG_FILE}: {root_ws:?}\n\
967	             {}/{VC_CONFIG_FILE}: {bot_ws:?}",
968	            root.display(),
969	            bot.display()
970	        )
971	        .into());
972	    }
973	    Ok(())
974	}
