/// (root-anchored) or pre-0.75.0 `workspace.other-repo` (bare
/// name). Used by the root walk to point the legacy fix-it at the
/// work-side root, and as [`is_bot_dir`]'s backward-compat
/// fallback.
fn legacy_is_bot_dir(dir: &Path) -> bool {
    let Ok(dir) = dir.canonicalize() else {
